"""Add original browser compute and peer communication curriculum."""
import copy
import datetime
import html
import json
import re
import subprocess
import uuid
from pathlib import Path

root = Path(__file__).resolve().parents[1]
fixture = root / 'src/data/fixtures.json'
entries = json.loads(fixture.read_text())
by_path = {entry['path']: entry for entry in entries}
stamp = datetime.datetime.now(datetime.UTC).isoformat()

def p(value):
    return '<p>' + html.escape(value) + '</p>'

def link(path):
    assert path in by_path, path
    return '<a href="/' + html.escape(path, quote=True) + '">' + html.escape(by_path[path]['title']) + '</a>'

hubs = [
    dict(path='web-tech/webassembly-and-browser-compute', title='WebAssembly and Browser Compute', summary='Ship bounded client-side compute with explicit loading, memory, worker, and fallback contracts.', overview='A binary module can keep selected compute near the user, but it does not erase download time, memory copies, device limits, or the JavaScript boundary. This track follows a document-review tool that reads a user-selected image, extracts a local measurement, and discards the bytes when the task ends. The lessons separate module loading from memory ownership, main-thread responsiveness, and capability policy. They also show where a server or plain JavaScript path remains simpler. A module receives only capabilities the host supplies; application permissions still belong to the host.', bridges=['web-tech/browser-execution-and-resource-lifecycle','web-tech/offline-and-device-capabilities']),
    dict(path='web-tech/webrtc-and-peer-media-sessions', title='WebRTC and Peer Media Sessions', summary='Establish authorized peer sessions while controlling capture, signaling, transport, and teardown.', overview='A browser call combines several separate systems: permission to capture, application permission to join, a signaling exchange, network path discovery, transport state, and local user controls. This track follows a private case-review consultation where two reviewers may speak and exchange small annotations. It covers consent and track lifetime, room-scoped signaling, ICE and relay decisions, and bounded data-channel writes. The application must recover from denial, disconnect, tab closure, and stale room membership without exposing case content in signaling logs.', bridges=['web-tech/media-and-live-updates','web-tech/identity-and-application-security']),
]

topics = [
    dict(hub=0, slug='wasm-loading-artifact-and-fallback-contract', title='Wasm Loading, Artifact, and Fallback Contract', summary='Load a versioned module only when the workflow needs it and retain a usable fallback.',
    concept='WebAssembly is a compilation target for constrained executable code. The browser compiles and instantiates a module, then JavaScript calls exports and supplies any imports. That boundary is a contract: a module cannot read a case record or open a camera unless the host gives it a path. A shipped artifact needs a version, an integrity and cache plan, and a fallback when compilation, delivery, or device support fails. Loading a module before a user begins a task can charge every visitor for work only a few perform.',
    case='A reviewer selects a 47-megabyte scan to classify locally. The editor requests a pinned decoder artifact only after the reviewer starts analysis. Its server returns the binary with the expected media type and a long-lived hashed URL. If the network is offline but an approved cached copy exists, the editor may use that exact version. If instantiation fails, the UI keeps the scan and offers a slower local JavaScript path or an explicitly consented server job. The reviewer sees which path is active; no silent upload occurs.',
    design='Use streaming instantiation when the response and browser support it, but account for servers that return the wrong media type or a non-streaming fallback. Validate a response before passing it to compilation. Version the JavaScript adapter and binary as one compatible release; an old cached adapter calling a new export name fails at runtime. Keep inputs bounded before allocating memory. If the module includes third-party code, audit its imports, license, and build chain separately from the public tutorial. Treat successful loading as a capability check, not proof of correct output.',
    cost='Cold start includes download, compile, initialization, and input-copy time. Cached compilation can help repeat sessions but is browser controlled, so do not promise a fixed cache hit. For one small calculation, JavaScript may win because crossing into a module has overhead. Measure end-to-end task time on slow devices, not only the inner function. Record artifact version and coarse failure class without retaining scan bytes. A large binary can hurt page delivery even when its inner loop is fast.',
    failure='A CDN returns the binary as generic text, so streaming compilation rejects it while a developer workstation succeeds. The adapter shows a blank result and clears the selected file. Fix the response configuration, keep user input, and activate the tested fallback. A second failure pairs a stale adapter with a changed export signature. Test version mismatch, partial download, compilation rejection, offline load, an empty scan, a very large scan, and a user who cancels before the binary arrives.',
    drill='Load two compatible artifact versions in a test environment. Block the binary request after a reviewer selects a scan; the form must retain the file and explain the fallback. Return an unexpected content type and confirm a controlled retry path. Time both cold and warm runs on a low-memory device. Compare final output from the module and fallback for the same 47-page fixture, then prove the scan is not uploaded when the reviewer chose local processing.',
    decision='Adopt the module only when measured end-to-end work improves and the ordinary workflow survives artifact failure.',
    code='function chooseDecoder(binaryReady, localFallbackReady) {\n  return binaryReady ? "wasm" : localFallbackReady ? "javascript" : "unavailable";\n}\nconsole.log(chooseDecoder(false, true));\n// Output: javascript',
    checks=['Failed loading preserves selected user input.','Adapter and binary versions are compatible.','Fallback never uploads private bytes without consent.'], mistakes=['Measuring only the module function.','Treating a cached artifact as guaranteed available.','Clearing form state after compilation fails.'], related=['web-tech/service-worker-offline-fallback','web-tech/http-delivery-and-cache-ownership']),
    dict(hub=0, slug='wasm-linear-memory-ownership-and-copy-cost', title='Wasm Linear Memory, Ownership, and Copy Cost', summary='Make byte ownership, allocation limits, and view invalidation visible at the JavaScript boundary.',
    concept='A module often reads a linear memory shared with its JavaScript host. Bytes move through typed views; pointer and length values identify regions inside the module allocation. A safe wrapper checks bounds, owns allocation and release, and copies results before freeing memory that backs them. On ordinary non-shared memory, growth replaces the buffer and old JavaScript views become detached. That detail breaks code that stores one Uint8Array for an entire editing session. A pointer is not a durable object identifier.',
    case='The scan tool crops an image into tiles. Tile 29 is copied into a module allocation, processed, copied back to a fresh JavaScript buffer, and then released. Another scan needs more pages of memory; the module grows, so the wrapper obtains a new view before reading tile 47. The first reviewer closes the editor halfway through; a finally block releases the allocation and revokes any object URL. The server never sees the pixel buffer, and the UI can discard the result on account switch.',
    design='Put allocation, range check, call, copy-out, and release behind one adapter function. Check that offset and length are safe integers and that offset plus length remains within the current buffer. Treat an exported allocator and deallocator as one matched pair; do not free memory the host does not own. Recreate typed views after any operation that can grow ordinary memory. A shared-memory build has different view behavior and concurrency constraints, so document it separately. Limit input dimensions before calculating byte counts to avoid overflow and device exhaustion.',
    cost='Copy-in and copy-out are O(n) in bytes even when the module algorithm is faster than its JavaScript equivalent. Peak memory can include the source file, decoded image, module memory, output copy, and canvas backing store at once. A nominal 47-megabyte file can expand considerably when decoded into pixels. Partition work into bounded tiles and release each one. Measure peak resident memory and long-task duration alongside throughput. Zero-copy claims require proof that lifetime and ownership are safe.',
    failure='A cached Uint8Array points to a detached buffer after memory growth, and the second crop reads zero bytes. A different wrapper frees an output pointer before copying its bytes, so results vary with later allocations. Test forced growth, maximum-size inputs, zero-length slices, near-end offsets, allocation failure, cancellation, repeated scans, and simultaneous edits. For privacy, ensure discarded buffers are no longer reachable from application state; freeing a pointer alone does not guarantee secret erasure.',
    drill='Process tiles sized 47 and 62 units through an adapter that forces one memory growth between calls. Compare bytes before and after the growth, then recreate the view. Inject an allocator failure and verify every earlier allocation is released. Record peak memory for one large scan and compare tiled processing with a whole-image copy. Finally switch accounts and inspect whether any pixel buffer remains attached to a component or worker message.',
    decision='Wrap the pointer boundary once, cap allocations, and price byte copies as part of the algorithm.',
    code='function validRegion(offset, length, capacity) {\n  return Number.isSafeInteger(offset) && Number.isSafeInteger(length) && offset >= 0 && length >= 0 && offset <= capacity && length <= capacity - offset;\n}\nconsole.log(validRegion(47, 62, 100));\n// Output: false',
    checks=['Every module allocation has one owner and release path.','Views are refreshed after ordinary memory growth.','Offset and length are checked before reads or writes.'], mistakes=['Keeping a stale typed view after growth.','Returning a view after freeing its backing region.','Comparing compute time while ignoring copy and decode cost.'], related=['web-tech/cooperative-main-thread-scheduling','web-tech/upload-intake-budgets-and-storage-ownership']),
    dict(hub=0, slug='wasm-worker-jobs-cancellation-and-result-order', title='Wasm Worker Jobs, Cancellation, and Result Order', summary='Run expensive modules off the main thread with bounded queues and stale-result protection.',
    concept='Moving computation to a Worker preserves UI responsiveness, but it does not make CPU or memory free. The main thread and worker exchange messages; transfers can move ownership of an ArrayBuffer, while ordinary structured cloning may copy data. A job contract needs an identity, input limit, progress rule, cancellation behavior, and output version. A worker still running an old request can return after a newer selection, so the editor must reject stale results rather than replacing the current scan.',
    case='A reviewer starts extraction on scan 29, then selects scan 47 before the first job finishes. The editor increments its job generation and tells the worker to cancel the old task. The module cannot interrupt an already-running synchronous export, so the UI also ignores any response tagged with the old generation. Only scan 47 may update the visible result. When the reviewer leaves the page, the controller terminates an unresponsive worker and releases the associated buffer instead of leaving CPU work alive in a hidden tab.',
    design='Create a small worker pool only after observing throughput needs; one worker is often sufficient for a single editor. Give each job a stable ID and generation, then cap queue depth and input size. Prefer transferable buffers when the sender no longer needs the bytes, and never read a transferred buffer afterward. Support cooperative cancellation between chunks; for non-interruptible native calls, reject stale output and terminate the worker only when that cost is acceptable. Carry errors back as structured codes without private payloads. Keep DOM and media permission work on the main thread.',
    cost='Posting a large clone can add O(n) copying and peak memory. A transfer avoids that copy but changes who owns the buffer. A pool of four workers can quadruple memory pressure while competing for the same device cores. Progress messages also cost scheduling and can flood rendering if emitted for every tile. Measure input-to-result latency, long tasks on the main thread, worker startup, queue wait, cancellation delay, and peak memory. Browser scheduling can vary when a tab is backgrounded.',
    failure='The reviewer sees scan 29 analysis over scan 47 because an old result arrived last. Add a generation check at the UI reducer. Another implementation transfers the only source buffer, then tries to create a preview from the detached sender-side bytes. Test rapid file changes, two queued jobs, termination during allocation, a background tab, a worker crash, stale progress messages, and a retry after cancellation. Confirm errors do not serialize the selected document into telemetry.',
    drill='Start two jobs in reverse completion order and prove the latest selection wins. Transfer a buffer, then assert the sending owner no longer uses it. Cap queue depth at two; the third request should replace or reject work according to the product rule. Force the worker to hang and terminate it while keeping the editable form available. Measure a low-powered device with one worker and with multiple workers before choosing concurrency.',
    decision='Use a worker for responsiveness, then define ownership and stale-result rules separately from compute correctness.',
    code='function acceptWorkerResult(currentGeneration, resultGeneration) {\n  return currentGeneration === resultGeneration;\n}\nconsole.log(acceptWorkerResult(47, 29));\n// Output: false',
    checks=['Older jobs cannot overwrite a newer selection.','Buffers have one sender or receiver owner after transfer.','Worker failure leaves the editor recoverable.'], mistakes=['Assuming cancellation interrupts a synchronous export.','Starting one worker per tile without a memory budget.','Cloning a large buffer and measuring only module time.'], related=['web-tech/cooperative-main-thread-scheduling','web-tech/asynchronous-field-validation-races']),
    dict(hub=0, slug='wasm-capabilities-isolation-and-performance-budget', title='Wasm Capabilities, Isolation, and Performance Budget', summary='Keep module authority narrow and require measured benefit before adding shared-memory complexity.',
    concept='A module runs inside a host environment with explicit imports and memory access, but sandboxing does not validate its business output or make untrusted input harmless to the surrounding workflow. Imports can expose logging, clocks, network wrappers, or storage; each import expands authority. Shared-memory or threaded builds introduce concurrency and cross-origin isolation requirements in browser deployments. Ordinary single-threaded Wasm does not require those headers. A thread choice also affects third-party resource loading and deployment policy, so it belongs in an architecture decision.',
    case='The scan classifier asks for a clock and a bounded memory region. It does not receive a fetch wrapper or the current case token. A new build claims a faster threaded path, but the site embeds a third-party review widget that fails under the proposed isolation headers. The team measures both builds on low-end reviewer devices. The single-threaded worker path meets the task budget, so it ships without imposing isolation on every page. If a later workload justifies threads, the team tests an isolated route and all embedded assets first.',
    design='Inventory imports and remove anything the module does not need. Validate untrusted file type and dimensions before invoking native processing. Bound module memory, execution time, and output size at the host boundary; a worker can be terminated if the module stalls. For a shared-memory build, check actual cross-origin isolation in the document and worker and test resource policies in staging. Avoid treating a thread count as a proxy for speed. Keep a plain JavaScript or server path for devices and environments that cannot run the chosen build.',
    cost='Threading can increase parallel throughput for large independent workloads, yet startup, synchronization, contention, and duplicate worker stacks consume memory. Isolation headers may require changes to third-party scripts and embedded resources, raising integration cost. Security review of binary supply and imports also costs time. Record total job latency, peak memory, worker count, crashes, fallback share, and affected third-party assets. A module that wins only on a desktop benchmark may be a net loss for the actual user devices.',
    failure='The team enables shared memory on the main site without checking isolation; the threaded build fails and the embedded widget stops loading. A fallback test passes locally but was not included in the production bundle. Test isolation false, third-party resource denial, unsupported module features, malformed input, an infinite loop, memory growth to the cap, and a compromised import wrapper. Verify the app never passes case tokens or private record bodies as imports merely for debugging convenience.',
    drill='List every import of a compiled classifier and justify each one. Run the single-threaded and threaded versions against a 47-page fixture on two device classes. Deliberately remove isolation headers and confirm the product picks a safe path. Load a third-party widget under the planned policy, then force the module to stall and verify worker termination. Compare the complete interaction budget, including download and result display, before approving the extra deployment surface.',
    decision='Keep authority minimal and accept a more complex build only after it improves the measured user task.',
    code='function computeMode(isolated, threadedArtifactReady) {\n  return isolated && threadedArtifactReady ? "threaded" : "single-worker";\n}\nconsole.log(computeMode(false, true));\n// Output: single-worker',
    checks=['Imports expose no case token or unnecessary network access.','Threaded mode has a tested isolation and fallback path.','Performance compares complete user tasks on target devices.'], mistakes=['Assuming every Wasm module needs cross-origin isolation.','Equating more workers with lower latency.','Trusting a sandbox to validate output or business permissions.'], related=['web-tech/browser-security-and-data-stewardship','web-tech/load-tests-and-capacity-budgets']),
    dict(hub=1, slug='media-capture-consent-and-track-lifecycle', title='Media Capture Consent and Track Lifecycle', summary='Request the minimum camera or microphone capability and release every track on exit.',
    concept='Media capture begins with a secure browser context, user permission, and a product decision about what to request. A browser permission prompt does not prove the person may join a private case room; application authorization is separate. A MediaStream owns tracks that can remain active after a component hides its preview unless they are stopped. Muting a track and stopping it are different actions. The interface should show local capture state, recover from denial, and let a participant leave without waiting for a remote peer.',
    case='Reviewer 29 joins a case consultation with audio only. The page explains the request before calling capture; no camera permission is requested. Reviewer 29 denies the microphone once, so the room remains readable and offers typed notes rather than re-prompting in a loop. On a later attempt, capture succeeds and a clear local indicator appears. Reviewer 29 leaves while the remote peer is disconnected; the local audio track stops immediately, the peer connection closes, and the UI shows that capture ended.',
    design='Request only the tracks needed for the current feature. Handle missing device, denied permission, device-busy error, and a track ending unexpectedly. Bind capture lifetime to one session controller rather than a rendering component that may mount twice. Stop tracks on explicit leave, room revocation, page transition, and setup failure after partial acquisition. Do not assume setting enabled to false releases hardware; stop the track when the session ends. Recheck room membership on the server before signaling, and avoid recording media by default.',
    cost='Camera capture spends power, bandwidth, and CPU even before the remote path becomes useful. Higher resolution can increase encode cost, so choose constraints from the actual consultation need and allow degradation. Repeated permission prompts erode trust and can leave a participant stuck without a fallback. Measure setup failure categories, active track duration, unexpected track ends, and leave-to-stop delay with no media content in metrics. Device behavior and permission persistence differ across browsers; test rather than assuming one prompt pattern.',
    failure='A reviewer closes the consultation drawer, but the microphone light stays on because the stream is stored in a page-level variable. A second path catches a connection error but never stops a track already acquired. Test close before signaling, denied permission, missing microphone, duplicate mount, remote disconnect, account switch, route navigation, and leave during capture. Confirm each path stops every owned local track and removes references to the preview stream.',
    drill='Open an audio-only session, deny the first prompt, and verify text notes remain available. Grant permission, then close the drawer before an answer arrives. Inspect each track readyState and the browser capture indicator. Repeat while switching accounts and while the remote peer drops. Finally request a nonexistent input device and ensure the error text identifies a recoverable choice without copying device labels into general telemetry.',
    decision='Tie capture to explicit user intent and session lifetime, with release independent of signaling success.',
    code='function mayRequestCapture(secureContext, roomAllowed, userIntent) {\n  return secureContext && roomAllowed && userIntent;\n}\nconsole.log(mayRequestCapture(true, true, false));\n// Output: false',
    checks=['A denied prompt leaves a usable non-media path.','Every acquired track stops on leave and failed setup.','Room access is checked apart from device permission.'], mistakes=['Requesting camera for an audio-only room.','Treating mute as hardware release.','Letting a hidden component retain an active stream.'], related=['web-tech/permission-request-timing-and-manual-fallback','web-tech/object-level-authorization-for-reads-and-writes']),
    dict(hub=1, slug='webrtc-signaling-room-auth-and-offer-order', title='WebRTC Signaling, Room Authorization, and Offer Order', summary='Exchange descriptions and candidates through an authorized, ordered room protocol.',
    concept='WebRTC leaves signaling to the application. Peers must exchange session descriptions and connectivity candidates through a separate channel, and that channel must decide who belongs to a room. A description is not proof of user identity. Offer and answer state changes are asynchronous; reordered or replayed messages can apply to the wrong connection attempt. A room protocol therefore needs authenticated participants, a session generation, message type, bounded payload, sequence or dedupe rule, and expiry. The server should not broadcast private room messages to every connected browser.',
    case='Reviewers 29 and 47 are assigned to consultation room 62. Reviewer 29 sends an offer tagged generation 6. Reviewer 47 answers, and both exchange candidates for that generation. Reviewer 47 loses case access while a stale candidate is in flight; the signaling server denies later messages and closes the subscription. A delayed answer from generation 5 arrives after a reconnect and is ignored. Neither case title nor annotation text is embedded in the signaling event.',
    design='Authorize join and every signaling message against current room membership, not only a one-time room token. Bind messages to a room ID, sender identity, recipient identity, and generation. Validate description and candidate types and size before forwarding. Apply remote descriptions in the right peer state, then add candidates when their associated remote description is available. Define how both sides handle simultaneous offers, reconnects, and a closed room; a simple product may nominate one offerer to reduce glare. Keep logs coarse and expire stored signaling messages quickly.',
    cost='Signaling traffic is usually small compared with media, but retries and candidate bursts can fill a room service if messages are unbounded. Membership checks may require a cached authorization decision with a short lifetime and revocation path. Ordering metadata costs a few bytes per event and saves difficult reconnection bugs. Measure offer-to-answer latency, rejected generations, denied room messages, failed state transitions, and room cleanup delay. Do not use peer connection success to infer that the signaling server enforced access.',
    failure='A stale answer from an earlier call is applied to a new RTCPeerConnection and throws a state error. Another server trusts a room ID supplied by the browser and forwards candidates to a reviewer removed from the case. Test simultaneous join, duplicate offer, out-of-order candidate, late answer, revoked membership, two open tabs, and a room closed before media starts. Ensure a failed negotiation does not leave a local microphone track running.',
    drill='Write a message schema for room 62 with sender, recipient, generation, type, and bounded payload. Replay generation 5 after generation 6 begins and verify rejection. Remove reviewer 47 mid-exchange and attempt to publish a candidate. Test simultaneous offers under the selected offerer rule. Capture only coarse state-transition events in logs and confirm no private case text appears in the signaling envelope.',
    decision='Treat signaling as a private application protocol with authorization and ordering, not as a passive message pipe.',
    code='function acceptSignal(activeGeneration, messageGeneration, memberAllowed) {\n  return memberAllowed && activeGeneration === messageGeneration;\n}\nconsole.log(acceptSignal(6, 5, true));\n// Output: false',
    checks=['Every message is room-authorized.','Old generations cannot mutate a new negotiation.','Descriptions and candidates have bounded validated envelopes.'], mistakes=['Using a room identifier as authorization.','Applying a delayed answer to a new connection.','Logging private case content with signaling events.'], related=['web-tech/sse-and-websocket-choice','web-tech/live-update-reconnect-and-order']),
    dict(hub=1, slug='webrtc-ice-turn-fallback-and-session-recovery', title='WebRTC ICE, TURN Fallback, and Session Recovery', summary='Budget relay paths, observe connection state, and recover without implying direct connectivity.',
    concept='ICE gathers candidate network paths and tests which pair can carry the connection. STUN helps discover reachable addresses; TURN can relay traffic when a direct path is unavailable. A successful offer-answer exchange does not guarantee media flow. Corporate networks, firewalls, mobile handoffs, and expired relay credentials can all change the path after setup. A product should state a connection timeout, retry rule, relay budget, and user-facing fallback. It should not promise peer-to-peer routing for every call.',
    case='Reviewer 29 calls reviewer 47 from an office network that blocks direct paths. Their descriptions exchange correctly, but direct candidates fail. A scoped TURN credential lets the call connect through a relay. Twenty minutes later reviewer 29 changes networks and the connection enters a failed state. The interface reports an interrupted call, attempts one controlled ICE restart when both room memberships still hold, and falls back to typed notes if recovery does not finish in the budget. Local capture stops when the reviewer leaves.',
    design='Configure both discovery and relay options from a trusted server; avoid long-lived relay secrets embedded in browser bundles. Watch iceConnectionState and connectionState, while remembering that temporary disconnected states need a short grace period. Use an ICE restart or rebuild according to the browser API and product state, but associate the new negotiation with a generation so old candidates do not contaminate it. Renew short-lived relay credentials when needed. Verify current room permission before retrying. Keep text collaboration available when media cannot connect.',
    cost='TURN relays carry media bytes and can dominate bandwidth cost. Restrict relay credentials by expiry and usage policy and monitor relay share, bytes, duration, and failures by coarse network class. Aggressive retries can add server load and repeated permission confusion while doing little for blocked networks. A direct path may lower relay cost but is not guaranteed and should not be used as a security claim. Test latency and quality under packet loss, not just successful establishment. Reserve capacity for expected simultaneous consultations.',
    failure='The team treats signaling completion as call success, so both reviewers see “connected” while no ICE pair succeeds. Another implementation retries indefinitely with an expired relay credential and never offers notes. Test direct-path failure, relay-only network, expired credentials, packet loss, mobile handoff, a brief disconnect, a permanent failure, and room revocation during restart. Ensure telemetry says whether a relay was used without recording remote addresses or media content unnecessarily.',
    drill='Run room 62 in a network profile that blocks direct candidates but permits the configured relay. Measure time from offer to media flow and record relay bytes for a 47-minute session. Expire credentials, then test one renewal and one failure path. Simulate a mobile network handoff and compare a short grace period with immediate teardown. Revoke case access before restart and verify the application stops reconnecting.',
    decision='Design for relay and failure as ordinary states, with bounded recovery and an accessible non-media path.',
    code='function connectionAction(state, retries, maximumRetries) {\n  return state === "connected" ? "continue" : retries < maximumRetries ? "retry" : "notes";\n}\nconsole.log(connectionAction("failed", 2, 2));\n// Output: notes',
    checks=['Relay-only networks can connect with scoped credentials.','Recovery stops after a named budget.','Room revocation prevents reconnection.'], mistakes=['Equating SDP exchange with connected media.','Shipping permanent TURN credentials to browsers.','Retrying forever without a usable fallback.'], related=['web-tech/sse-and-websocket-choice','web-tech/request-deadlines-retries-and-backoff']),
    dict(hub=1, slug='data-channel-backpressure-and-peer-state', title='Data Channel Backpressure and Peer State', summary='Bound annotation messages and keep durable case state outside the peer transport.',
    concept='A data channel can carry small application messages between peers once its connection is open. Calling send queues bytes; bufferedAmount reveals queued user-agent data, not an unlimited delivery promise. Message order and reliability depend on channel configuration. A peer channel is transient, so a durable case decision still belongs in an authorized server write with revision and idempotency rules. The peer path can carry ephemeral cursor or annotation hints, but the server remains the record of truth for decisions that must survive either participant leaving.',
    case='During a consultation, reviewer 29 points to region 47 of a scan and sends an annotation hint. Reviewer 47 sees it immediately, but the actual case note is saved through the case API with an expected revision. When the peer channel pauses, reviewer 29 can continue editing locally; the client stops sending hints once buffered bytes cross its limit. When the channel returns, it may send the latest cursor position rather than replaying every obsolete movement. The saved note remains available even if the peer never reconnects.',
    design='Choose the channel reliability and ordering settings to match each message class. Keep payloads small, validate schema and maximum size at both endpoints, and never infer authorization from a live peer connection. Gate send on open state and a bounded bufferedAmount threshold; resume after bufferedamountlow or a fresh state check. Coalesce replaceable events such as pointer movement. For durable actions, call a server endpoint that checks current room and object permissions, revision, and idempotency key. On leave, close the data channel, connection, and media tracks.',
    cost='Per-message overhead can exceed useful data if every pointer pixel becomes an event. Coalescing reduces network and render work from O(movements) toward O(display frames) for ephemeral state. Reliable ordered delivery can let one large message delay later ones, while weaker delivery can drop hints; neither is a replacement for persistence. Track queue depth, dropped or coalesced hints, end-to-end hint delay, server-save conflict rate, and channel closure. Avoid putting raw private documents in this transport merely because it is encrypted.',
    failure='A drag gesture emits thousands of messages while the network slows, and bufferedAmount grows until the tab runs out of memory. Add a threshold and coalesce hints. Another implementation treats a received peer message as a committed case note; when the remote tab closes, the note vanishes from history. Test closed and closing channel states, malformed payload, a large message, slow network, peer reconnect, stale case rights, duplicate server save, and a conflict between two editors.',
    drill='Send 62 pointer updates under a throttled link and enforce a 47-kilobyte queue cap. Verify the latest visible position wins while old positions may be discarded. Save a note through the server, close the peer connection, and reload the case: the note must still exist. Revoke reviewer 47 and attempt a new durable write from that browser; the server must reject it even if an old data channel remains open.',
    decision='Use the peer channel for bounded ephemeral interaction and the authorized server contract for durable state.',
    code='function maySendHint(channelState, bufferedBytes, maximumBytes) {\n  return channelState === "open" && bufferedBytes < maximumBytes;\n}\nconsole.log(maySendHint("open", 48000, 47000));\n// Output: false',
    checks=['Buffered data has a hard application limit.','Durable notes survive peer teardown through the case API.','Live channel state never grants case permission.'], mistakes=['Sending every pointer movement without coalescing.','Assuming send means remote persistence.','Ignoring a closed channel when queueing messages.'], related=['web-tech/idempotent-write-requests','web-tech/sse-and-websocket-choice']),
]

assert len(hubs) == 2 and len(topics) == 8
for number, hub in enumerate(hubs):
    path = hub['path']
    assert path not in by_path
    entry = copy.deepcopy(by_path['web-tech/production-signals-and-incident-decisions'])
    entry.update(id=str(uuid.uuid5(uuid.NAMESPACE_URL, 'aitrove:' + path)), path=path, title=hub['title'], summary=hub['summary'], sort_order=2870 + number, created_at=stamp, updated_at=stamp, published_at=stamp)
    entry['data'] = {'subject_root':'web-tech/web-technology','section_path':path,'content_format':'html','seo_ready':False,'modules':[],'resource_tabs':[{'title':'Web Development','path':'web-tech/web-technology'},{'title':'Projects','path':'web-tech/web-technology/project'},{'title':'Quizzes','path':'web-tech/quizzes'}]}
    entries.append(entry)
    by_path[path] = entry

for number, topic in enumerate(topics):
    path = 'web-tech/' + topic['slug']
    assert path not in by_path
    subprocess.run(['node','--check','--input-type=module'], input=topic['code'], text=True, capture_output=True, check=True)
    entry = copy.deepcopy(by_path['web-tech/trace-context-across-request-and-job'])
    entry.update(id=str(uuid.uuid5(uuid.NAMESPACE_URL, 'aitrove:' + path)), path=path, title=topic['title'], summary=topic['summary'], sort_order=2880 + number, created_at=stamp, updated_at=stamp, published_at=stamp)
    hub_path = hubs[topic['hub']]['path']
    related = [hub_path] + ['web-tech/' + item['slug'] for item in topics if item['hub'] == topic['hub'] and item['slug'] != topic['slug']] + topic['related']
    body = p(topic['concept']) + '<h2>Working case</h2>' + p(topic['case'])
    body += '<h2>Implementation boundary</h2><pre><code class="language-javascript">' + html.escape(topic['code'], quote=False) + '</code></pre>' + p(topic['design'])
