    body += '<h3>Common Mistakes</h3><ul>' + ''.join('<li>' + html.escape(item) + '</li>' for item in topic['mistakes']) + '</ul>'
    entry['body'] = body
    entry['data'] = {'subject_root':'web-tech/web-technology','section_path':hub_path,'content_format':'html','seo_ready':False,'kind':'tutorial','author_path':'authors/aitrove-editorial','reading_minutes':7,'related':related}
    entries.append(entry)
